import * as THREE from './vendor/three.module.js';
import {makeGhost,makeMisfit,CHARACTERS as REFERENCES,MISFITS} from './model.js';
import {ghostPortrait} from './board.js';
const ORDER=['moss','blu','ember'],pick=list=>ORDER.map(id=>list.find(c=>c.id===id)),$=id=>document.getElementById(id);
// The featured set is the trio that plays on the board; the v003 reference sculpts stay available as a second set.
const SETS={
misfits:{chars:pick(MISFITS),build:(id,s)=>makeMisfit(id,s),portrait:id=>makeMisfit(id,1,{fangSize:1.35}),file:id=>`assets/ghosts/v002/${id}-v002.glb`,badge:'LITTLE MISFITS / 002',stage:'LITTLE MISFITS · V002',eyebrow:'THE PIECES ON THE BOARD',title:'Three little misfits.<br><span>Fangs, horns &amp; sleepy eyes.</span>',lead:'Blu, Ember and Moss exactly as they play: one tiny fang, two cheeky fangs, and one very slow blink.',archive:['assets/ghosts/little-misfits-v002.zip','Download the Little Misfits','All five misfits as GLBs + lineup + manifest'],manifest:'assets/ghosts/v002/manifest.json',note:'Bent cat ears, crooked horns, tiny fangs, heavy eyelids, and pinched clay creases. These are the same models that hop around the board.',footer:'The playing pieces of 5 Senses.',kind:c=>c.ears==='cat'?'CAT GHOST':c.ears==='horns'?'HORNED GHOST':'BLOB GHOST'},
references:{chars:pick(REFERENCES),build:(id,s)=>makeGhost(id,s),portrait:id=>makeGhost(id,1),file:id=>`assets/ghosts/v003/${id}-reference-v003.glb`,badge:'REFERENCE COLLECTION / 003',stage:'REFERENCE MODELS · V003',eyebrow:'SCULPTED WITH A LITTLE MISCHIEF',title:'Three little originals.<br><span>Back to their clay roots.</span>',lead:'Brown-gray. Blue. Red-orange. A closer match to the cover and the real clay figures.',archive:['assets/ghosts/original-three-v003.zip','Download the reference sculpts','3 individual GLBs + group scene + manifest'],manifest:'assets/ghosts/v003/manifest.json',note:'Large uneven cream eyes, simple mouths, puddled hems, and softly dented clay. Based on the supplied cover and physical figures.',footer:'Modeled from the supplied clay references.',kind:c=>c.ears==='cat'?'CAT GHOST':'BLOB GHOST'}};
let set=location.hash==='#references'?'references':'misfits',selected=1,lineup=true,viewer=null;const portraits={};
function roster(){const s=SETS[set],pics=portraits[set];$('ghostRoster').innerHTML=s.chars.map((c,i)=>`<button class="ghost-choice" data-index="${i}" aria-pressed="${i===selected}" style="--ghost-color:${c.color}"><i aria-hidden="true"${pics?' class="portrait"':''}>${pics?`<img src="${pics[i]}" alt="">`:''}</i><span><b>${c.name}</b><small>${c.title}</small></span></button>`).join('');}
function select(i){selected=i;const s=SETS[set],c=s.chars[i];$('ghostRole').textContent=c.title.toUpperCase();$('ghostName').innerHTML=`${c.name}<span>0${i+1} / 03</span>`;$('ghostBadge').textContent=`${c.sense.toUpperCase()} · ${s.kind(c)}`;$('ghostBadge').style.background=c.accent;$('ghostDescription').textContent=c.description;$('ghostTraits').innerHTML=c.traits.map(t=>`<li>${t}</li>`).join('');$('ghostDownload').href=s.file(c.id);$('ghostDownload').innerHTML=`Download ${c.name}<span>↓</span>`;$('lineupBtn').textContent=lineup?`Focus on ${c.name} ↗`:'Show the whole family ↗';document.querySelectorAll('.ghost-choice').forEach((b,n)=>b.setAttribute('aria-pressed',n===i));viewer?.select(i,lineup);}
function showSet(name){set=name;const s=SETS[set];$('setBadge').textContent=s.badge;$('stageSet').textContent=s.stage;$('introEyebrow').textContent=s.eyebrow;$('introTitle').innerHTML=s.title;$('introLead').textContent=s.lead;$('archiveLink').href=s.archive[0];$('archiveText').textContent=s.archive[1];$('archiveSmall').textContent=s.archive[2];$('manifestLink').href=s.manifest;$('materialNote').textContent=s.note;$('footerNote').textContent=s.footer;document.querySelectorAll('.set-switch [data-set]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.set===set));history.replaceState(null,'',set==='references'?'#references':location.pathname);
// Roster chips show portraits rendered from each set's own models (plain clay blobs without WebGL).
if(viewer&&!(set in portraits)){try{portraits[set]=s.chars.map(c=>ghostPortrait(s.portrait(c.id),160));}catch(e){console.warn('Portraits unavailable',e);portraits[set]=null;}}roster();select(selected);}
try{const el=$('ghostCanvas'),renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;el.appendChild(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color('#deddd6');const camera=new THREE.PerspectiveCamera(30,1,.1,50);scene.add(new THREE.HemisphereLight('#ffffff','#b8b6a5',2));const key=new THREE.DirectionalLight('#fff2d5',3.3);key.position.set(-3,6,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-5,right:5,top:4,bottom:-4,near:.1,far:20});key.shadow.bias=-.0004;key.shadow.normalBias=.015;scene.add(key);const fill=new THREE.DirectionalLight('#d1def1',1);fill.position.set(3,2,-2);scene.add(fill);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:'#deddd6',roughness:1}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;floor.position.y=-.05;scene.add(floor);
const groups={};const ghostsOf=name=>groups[name]||=SETS[name].chars.map(c=>{const g=SETS[name].build(c.id,1.7);g.visible=false;scene.add(g);return g;});let yaw=-.12,pointer=null;const calm=matchMedia('(prefers-reduced-motion: reduce)').matches;
function cameraUpdate(){const w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/Math.max(h,1);camera.updateProjectionMatrix();const d=lineup?(camera.aspect<1.25?8/camera.aspect:7.5):6.7;camera.position.set(0,lineup?3.2:2.35,d);camera.lookAt(0,lineup?.62:.9,0);}new ResizeObserver(cameraUpdate).observe(el);cameraUpdate();
viewer={select(i,all){const chars=SETS[set].chars,current=ghostsOf(set);for(const [name,list] of Object.entries(groups))if(name!==set)list.forEach(g=>g.visible=false);current.forEach((g,n)=>{g.visible=all||n===i;g.position.set(all?(n-(chars.length-1)/2)*1.15:0,0,0);g.scale.set(1.7*chars[n].width*(all?.85:1),1.7*chars[n].height*(all?.85:1),1.7*(all?.85:1));});cameraUpdate();}};
el.addEventListener('pointerdown',e=>{pointer=e.clientX;el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(pointer===null)return;yaw+=(e.clientX-pointer)*.009;pointer=e.clientX;});const end=()=>pointer=null;el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const t=clock.getElapsedTime(),stop=Math.floor(t*12)/12;(groups[set]||[]).forEach((g,i)=>{g.rotation.y=yaw+(lineup?(i-2)*-.07:0);g.rotation.z=calm?0:Math.sin(stop*.75+i)*.012;g.position.y=calm?0:Math.max(0,Math.sin(stop*.9+i)*.018);});renderer.render(scene,camera);}frame();}catch(e){console.error('Ghost preview unavailable',e);$('studioError').hidden=false;}
document.querySelector('.set-switch').addEventListener('click',e=>{const b=e.target.closest('[data-set]');if(b&&b.dataset.set!==set)showSet(b.dataset.set);});
$('ghostRoster').addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b)select(Number(b.dataset.index));});$('lineupBtn').addEventListener('click',()=>{lineup=!lineup;select(selected);});showSet(set);
